            <div class="article-live-preview" id="article-live-preview"><div class="live-preview-art" id="live-preview-art">${a?.coverImage&&safeURL(a.coverImage)?`<img src="${escapeHTML(safeURL(a.coverImage))}" alt="">`:artSVG(artKindForCategory(a?.categorySlug||'vedas-upanishads'))}</div><div class="live-preview-copy"><span class="tag tag-lav" id="preview-category">${escapeHTML(a?.category||'Vedas & Upanishads')}</span><div class="live-preview-title" id="preview-title">${escapeHTML(a?.title||'Your headline will appear here')}</div><p id="preview-excerpt">${escapeHTML(a?.excerpt||'Your standfirst will appear here as you write.')}</p><div class="live-preview-meta"><span id="preview-author">${escapeHTML(a?.author||'ANANTA Desk')}</span><span id="preview-readtime">${readingTime(a?.content||'')} min read</span></div><div class="live-preview-body" id="preview-body">${renderMarkdown(a?.content||'')}</div></div></div>
