  function collectPageBlocks(form){
    if(!form)return [];
    return $$('[data-page-block]',form).map(card=>{
      const read=name=>card.querySelector(`[data-block-field="${name}"]`)?.value||'';
      return {id:card.dataset.blockId||id('block'),type:card.dataset.blockType||'text',eyebrow:read('eyebrow').trim(),title:read('title').trim(),body:read('body').trim(),image:safeURL(read('image'))||'',alt:read('alt').trim(),caption:read('caption').trim(),credit:read('credit').trim()};
    });
  }
  function pageBlockEditor(block,index){
    const type=block.type||'text';
    const labels={text:'Editorial text',image:'Image feature',quote:'Pull quote',callout:'Research note'};
    return `<article class="page-block-editor" data-page-block data-block-id="${escapeHTML(block.id||id('block'))}" data-block-type="${escapeHTML(type)}">
      <div class="page-block-editor-head"><div><span class="small-caps">SECTION ${String(index+1).padStart(2,'0')}</span><strong>${labels[type]||'Editorial text'}</strong></div><div class="page-block-actions"><button type="button" data-action="page-block-up" aria-label="Move section up" ${index===0?'disabled':''}>↑</button><button type="button" data-action="page-block-down" aria-label="Move section down">↓</button><button type="button" data-action="page-block-remove" aria-label="Remove section">×</button></div></div>
      <div class="field"><label>Section label</label><input data-block-field="eyebrow" maxlength="90" value="${escapeHTML(block.eyebrow||'')}" placeholder="Optional section label"></div>
      ${type!=='image'?`<div class="field"><label>${type==='quote'?'Quote heading / attribution':'Section heading'}</label><input data-block-field="title" maxlength="150" value="${escapeHTML(block.title||'')}" placeholder="Add a clear heading"></div>`:''}
      ${type==='image'?`<div class="field"><label>Image URL</label><input data-block-field="image" type="url" value="${escapeHTML(block.image||'')}" placeholder="https://…"></div><div class="field"><label>Choose uploaded image</label><select data-block-media><option value="">Choose from Media Library…</option>${mediaAssets.map(m=>`<option value="${escapeHTML(m.url||'')}" ${block.image===m.url?'selected':''}>${escapeHTML(m.name||'Uploaded image')}</option>`).join('')}</select></div><div class="field"><label>Image alt text</label><input data-block-field="alt" maxlength="180" value="${escapeHTML(block.alt||'')}" placeholder="Describe the image meaningfully"></div><div class="field"><label>Caption</label><input data-block-field="caption" maxlength="220" value="${escapeHTML(block.caption||'')}" placeholder="Optional image caption"></div><div class="field"><label>Credit / source</label><input data-block-field="credit" maxlength="220" value="${escapeHTML(block.credit||'')}" placeholder="Photographer, archive or licence credit"></div>`:`<div class="field"><label>${type==='quote'?'Quotation':'Section copy'}</label><textarea data-block-field="body" maxlength="8000" rows="${type==='quote'?3:6}" placeholder="${type==='quote'?'Write the verified quotation here.':'Use Markdown: paragraphs, ## headings, **bold**, quotations and lists.'}">${escapeHTML(block.body||'')}</textarea></div>${type==='quote'?`<div class="field"><label>Attribution</label><input data-block-field="credit" maxlength="180" value="${escapeHTML(block.credit||'')}" placeholder="Author · source reference"></div>`:''}`}
    </article>`;
  }
  function renderPageBlocks(blocks){
    return (Array.isArray(blocks)?blocks:[]).map(block=>{
      const type=block.type||'text';
      if(type==='image'){
        const image=safeURL(block.image||'');
        if(!image)return '';
        return `<figure class="cms-content-image"><img src="${escapeHTML(image)}" alt="${escapeHTML(block.alt||'')}" loading="lazy"><figcaption>${escapeHTML(block.caption||'')}${block.credit?`<span>${escapeHTML(block.credit)}</span>`:''}</figcaption></figure>`;
      }
      if(type==='quote')return `<blockquote class="cms-pullquote"><span class="cms-block-eyebrow">${escapeHTML(block.eyebrow||'A note to consider')}</span>${block.title?`<strong>${escapeHTML(block.title)}</strong>`:''}<p>${escapeHTML(block.body||'')}</p>${block.credit?`<cite>${escapeHTML(block.credit)}</cite>`:''}</blockquote>`;
      if(type==='callout')return `<aside class="cms-research-note"><span class="cms-block-eyebrow">${escapeHTML(block.eyebrow||'Research note')}</span>${block.title?`<h3>${escapeHTML(block.title)}</h3>`:''}<div>${renderMarkdown(block.body||'')}</div></aside>`;
      return `<section class="cms-editorial-block">${block.eyebrow?`<span class="cms-block-eyebrow">${escapeHTML(block.eyebrow)}</span>`:''}${block.title?`<h2>${escapeHTML(block.title)}</h2>`:''}<div class="article-copy">${renderMarkdown(block.body||'')}</div></section>`;
    }).join('');
  }
  function renderManagedPageContent(override){
    const legacy=String(override.bodyContent||'').trim();
    const blocks=renderPageBlocks(override.blocks||[]);
    if(!legacy&&!blocks)return '';
    return `<div class="container cms-managed-layout">${legacy?`<article class="article-copy cms-body-copy">${renderMarkdown(legacy)}</article>`:''}${blocks?`<div class="cms-page-blocks">${blocks}</div>`:''}</div>`;
  }
  function savePageDesignerDraft(form){
    if(!form)return;
    const key=form.dataset.page;if(!(key in pageBlueprints))return;
    const value=captureForm(form);value.blocks=collectPageBlocks(form);value._localSavedAt=nowISO();
    localPageDrafts[key]=value;
    try{localStorage.setItem('ananta-page-drafts',JSON.stringify(localPageDrafts));}catch(_){}
    const status=$('#page-save-status');if(status)status.textContent='Working copy saved on this device · not yet published';
  }
  function redrawPageBlockEditor(form,blocks){
    const host=$('#page-block-editor');if(!host)return;
    host.innerHTML=(blocks||[]).map(pageBlockEditor).join('')||'<div class="page-block-empty"><span>✧</span><strong>No custom sections yet</strong><p>Add a text feature, image, quote or research note. Each section appears in the preview at the right.</p></div>';
    syncPageDesignerPreview();savePageDesignerDraft(form);
  }

